def frechet_second_response(
    operator: np.ndarray, left_vertex: np.ndarray, right_vertex: np.ndarray, *,
    contact_vertex: np.ndarray | None = None, heat_length: float = 1.0,
    supertrace_weight: float = 1.0,
) -> float:
    """Mixed Hessian including a noncommuting pair and seagull contact."""

    matrix = np.asarray(operator, dtype=complex)
    left = np.asarray(left_vertex, dtype=complex)
    right = np.asarray(right_vertex, dtype=complex)
    if matrix.shape != left.shape or matrix.shape != right.shape:
        raise ValueError("operator and source vertices must have one shape")
    for name, value in (("operator", matrix), ("left vertex", left), ("right vertex", right)):
        if not np.allclose(value, value.conj().T, rtol=1.0e-12, atol=1.0e-12):
            raise ValueError(f"{name} must be Hermitian")
    eigenvalues, eigenvectors = np.linalg.eigh(matrix)
    left_eigen = eigenvectors.conj().T @ left @ eigenvectors
    right_eigen = eigenvectors.conj().T @ right @ eigenvectors
    response = np.sum(
        _loewner(eigenvalues, heat_length) * left_eigen * right_eigen.T
    )
    if contact_vertex is not None:
        contact = np.asarray(contact_vertex, dtype=complex)
        if contact.shape != matrix.shape:
            raise ValueError("contact vertex has wrong shape")
        if not np.allclose(contact, contact.conj().T, rtol=1.0e-12, atol=1.0e-12):
            raise ValueError("contact vertex must be Hermitian")
        contact_eigen = eigenvectors.conj().T @ contact @ eigenvectors
        response += (
            np.sum(regulator_first(eigenvalues, heat_length) * np.diag(contact_eigen))
        )
    return float(np.real_if_close(supertrace_weight * response))

def mechanical_background_action(spin_labels,sigma,rotation):
    """H_L,0=(lambda/r) sigma_spin^a R_ad sigma_weak^d; H_R,0=0.

    The sign follows the retained H_a=diag(Q sigma.a,-Q sigma.a).
    jmath=-i sigma_weak is already the physical doublet representation.
    Returned unit action includes every n2-times-(n0+n1) output.
    """
    if np.asarray(rotation).shape!=(3,3,3,3):raise ValueError('saved Ad_w required')
    inp=lepton_labels((0,1));out=lepton_labels((0,1,2,3))
    weak=np.array([[[0,1],[1,0]],[[0,-1j],[1j,0]],[[1,0],[0,-1]]],complex)
    matrix=np.zeros((len(out),len(inp)),complex)
    for oi,(nt,lrt,st,wt,mt,kt) in enumerate(out):
        if lrt!=0:continue
        for ii,(ns,lrs,ss,ws,ms,ks) in enumerate(inp):
            if lrs!=0 or nt not in range(abs(ns-2),ns+3,2):continue
            for mi,mg in enumerate((2,0,-2)):
                for ki,kg in enumerate((2,0,-2)):
                    g=_gaunt((nt,mt,kt),(2,mg,kg),(ns,ms,ks))
                    if g:
                        matrix[oi,ii]+=g*np.einsum('a,d,ad->',sigma[:,st,ss],weak[:,wt,ws],rotation[:,:,mi,ki])
    Iin=charged_embedding(spin_labels,inp);Iout=charged_embedding(spin_labels,out)
    return dict(input_labels=np.asarray(inp),output_labels=np.asarray(out),
        full_weak_background_unit_action=matrix,charged_input_embedding=Iin,
        charged_output_embedding=Iout,charged_background_unit_action=matrix@Iin,
        spin_sigma=sigma,weak_sigma=weak)

def mixed_direction(self, K_p, M_p):
    """Bind one direction for streaming output rows without a mixed-base cache."""
    E_p, DQ_p = self.directional_cotangent(K_p, M_p)
    mass_p = arb_mat(M_p.tolist())
    def contract(K_b, M_b, K_bp, M_bp):
        for name, value in [('K_bp', K_bp), ('M_bp', M_bp)]:
            checked(value, self.n, self.n, name)
        E_b = self.first_operator(K_b, M_b)
        E_bp = self.M.solve(K_bp-M_bp*self.A-M_b*E_p-mass_p*E_b)
        pair = trace_product(DQ_p, E_b)
        contact_mass = trace_product(self.Q, E_bp)
        return dict(value=pair+contact_mass, pair=pair, mixed_and_mass=contact_mass)
    return contract

def implicit_objective_adjoint(F_n, Gamma_n):
    """L=Gamma-eta^T F with F_n^T eta=Gamma_n^T at the common base."""
    if Gamma_n.nrows()!=1 or Gamma_n.ncols()!=F_n.nrows():
        raise ValueError('one objective-normal row required')
    eta=F_n.transpose().solve(Gamma_n.transpose())
    return eta,F_n.transpose()*eta-Gamma_n.transpose()
